// El id_solicitud viaja como query param en el link que Workflow 1 le manda al cliente.
// El Form Trigger pre-llena este campo oculto con el query param ?id_solicitud= (solo en modo producción).
const idSolicitud = $json.id_solicitud || null;

return {
  json: {
    ...$json,
    id_solicitud: idSolicitud
  }
};

const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const join = (v) => Array.isArray(v) ? v.filter((x) => x !== '' && x != null).join('; ') : ((v === undefined || v === null) ? '' : String(v));
const num = (v) => (v === '' || v === undefined || v === null) ? null : Number(v);
const bool = (v) => Array.isArray(v) ? v.some((x) => x !== '') : (v === true || v === 'true');
