const c = $('Consolidar criterios - Información en Línea').first().json;
const plan = (j.plan_en_linea || '').trim().replace(/^Plan\s+/i, '');
const noSeguro = plan === 'No estoy seguro / necesito ayuda' || plan === '';
return { json: {
  id_solicitud: j.id_solicitud || c.id_solicitud,
  servicio: 'Información en Línea',
  tipo_servicio: 'Informacion en Linea',
  ya_sabe_plan: noSeguro ? false : true,
  plan_deseado: noSeguro ? '' : plan,
